using SimplePZMapmaker.Core;
using SimplePZMapmaker.Core.Export;
using System.IO.Compression;
using System.Text.Json;
public static class WorldGeographyTests
{
 public static IEnumerable<(string,Action)> Cases(){
  yield return("world building spans adjacent sections without storing duplicate fragments",()=>{var w=WorldTests.Fixture(2);var b=new Building{X=100*256+250,Y=100*256+80,Width=16,Height=14};b.Design=BuildingDesigner.Generate(b,2,42);w.Buildings.Add(b);WorldAssembler.Validate(w);var left=WorldAssembler.ProjectSection(w,w.Maps[0]);var right=WorldAssembler.ProjectSection(w,w.Maps[1]);Check(left.Buildings.Single().X==250&&right.Buildings.Single().X==-6,"Projection origins wrong");Check(w.Maps.All(m=>m.Project.Buildings.Count==0),"Stored fragments invented");using var zip=new ZipArchive(new MemoryStream(NativeWorldExporter.Export(w)));Check(zip.Entries.Count(e=>e.Name.EndsWith(".lotheader"))==2,"Missing native cell");});
  yield return("world building rejects gaps water collisions and moving sections away",()=>{var w=WorldTests.Fixture(2);var b=new Building{X=25850,Y=25680,Width=16,Height=14};b.Design=BuildingDesigner.Generate(b,1,42);w.Buildings.Add(b);WorldAssembler.Validate(w);Reject(()=>WorldAssembler.Move(w,w.Maps[1].Id,103,100));w.Maps[1].Project.Terrain[80*256]=Terrain.Water;Reject(()=>WorldAssembler.Validate(w));});
  yield return("seam repair joins roads and rivers without erasing protected objects or source",()=>{var w=WorldTests.Fixture(2);w.Maps[0].Project.Terrain[20*256+255]=Terrain.Road;w.Maps[0].Project.Terrain[30*256+255]=Terrain.Water;var before=JsonSerializer.Serialize(w);var result=WorldSeams.Repair(w,"both");Check(result.ChangedCells>0&&result.World.Maps[1].Project.Terrain[20*256]==Terrain.Road&&result.World.Maps[1].Project.Terrain[30*256]==Terrain.Water,"Road/river remains disconnected");Check(before==JsonSerializer.Serialize(w),"Repair mutated original");WorldAssembler.Validate(result.World);});
  yield return("ASCII elevation keeps north-first order nodata and centre georeference",()=>{const string asc="ncols 2\nnrows 2\nxllcenter 32.005\nyllcenter 54.775\ncellsize 0.01\nNODATA_value -9999\n120 130\n100 -9999\n";var grid=ElevationSurvey.ParseAscii(asc,"EPSG:4326","Survey","CC0");Check(grid.Sample(32.005,54.785)==120&&grid.Sample(32.005,54.775)==100&&grid.Sample(32.015,54.775)==null,"Grid orientation or NODATA changed");var round=ElevationSurvey.ParseAscii(grid.ToAscii(),"EPSG:4326","Survey","CC0");Check(round.Values.SequenceEqual(grid.Values),"Export lost height samples");Reject(()=>ElevationSurvey.ParseAscii(asc,"EPSG:32636","Survey","CC0"));});
  yield return("ASCII elevation rejects incomplete values and projected degrees confusion",()=>{Reject(()=>ElevationSurvey.ParseAscii("ncols 2\nnrows 2\nxllcorner 32\nyllcorner 54\ncellsize .01\n10 20 30","EPSG:4326","Survey","CC0"));Reject(()=>ElevationSurvey.ParseAscii("ncols 1\nnrows 1\nxllcorner 500000\nyllcorner 6000000\ncellsize 30\n100","EPSG:4326","Survey","CC0"));});
  yield return("an outline in the free line along a seam becomes a shared building instead of being lost",()=>{var w=WorldTests.Fixture(2);w.GeoReference=new(){Bounds=new(){West=32,East=32.02,South=54.77,North=54.79},MetresPerTile=1};var projection=new GeographicProjection(w.GeoReference,100,100);
   object Way(int id,double x0,double x1){var points=new[]{(x0,80.4),(x1,80.4),(x1,94.4),(x0,94.4),(x0,80.4)}.Select(point=>{var g=projection.Geographic(point.Item1,point.Item2);return new{lon=g.Longitude,lat=g.Latitude};});return new{type="way",id,tags=new Dictionary<string,string>{{"building","house"}},geometry=points};}
   // 256.4..268: starts on the second section's first column, which that section keeps free (CanPlace) -> "Outside the map" there
   var json=JsonSerializer.Serialize(new{elements=new[]{Way(1,256.4,268.6),Way(2,230.4,243.6)}});var notes=new List<string>();var result=GeographicImporter.ImportWorldBuildings(json,w,42,notes);
   Check(result.Added==1&&w.Buildings.Single().SourceId=="osm-way-1","Seam-margin outline was not shared, or an inner outline was");WorldAssembler.Validate(w);
   var section=w.Maps[1].Project;var local=GeographicImporter.Import(JsonSerializer.Serialize(new{elements=new[]{Way(1,256.4,268.6)}}),section,null,projection:new GeographicProjection(w.GeoReference,section.WorldX,section.WorldY));
   Check(local.Project.Buildings.Count==0&&local.SkipReasons.ContainsKey("Outside the map"),"The section importer should refuse the seam-margin outline");});
  yield return("OSM full footprint spanning sections becomes one common building",()=>{var w=WorldTests.Fixture(2);w.GeoReference=new(){Bounds=new(){West=32,East=32.02,South=54.77,North=54.79},MetresPerTile=1};var projection=new GeographicProjection(w.GeoReference,100,100);var points=new[]{(250d,80d),(266d,80d),(266d,94d),(250d,94d),(250d,80d)}.Select(point=>{var g=projection.Geographic(point.Item1,point.Item2);return new{lon=g.Longitude,lat=g.Latitude};});var json=JsonSerializer.Serialize(new{elements=new[]{new{type="way",id=42,tags=new Dictionary<string,string>{{"building","house"},{"building:levels","2"}},geometry=points}}});var notes=new List<string>();var result=GeographicImporter.ImportWorldBuildings(json,w,42,notes);Check(result.Added==1&&w.Buildings.Count==1&&w.Buildings[0].LevelsOrigin=="osm-levels"&&w.Buildings[0].SourceId=="osm-way-42","Boundary OSM building lost or duplicated");WorldAssembler.Validate(w);});
 }
 static void Check(bool ok,string msg){if(!ok)throw new Exception(msg);}static void Reject(Action action){try{action();}catch(ArgumentException){return;}throw new Exception("Expected rejection");}
}
